from rules import resolve


def solve(data):
    return resolve(data)

def _allowed_rows(name, package_rows, limits, blocked, pins):
    if name not in package_rows:
        return []
    low, high = limits.get(name, (None, None))
    forbidden = blocked.get(name, ())
    pin = pins.get(name)
    rows = []
    for row in package_rows[name]:
        version = row['version']
        if low is not None and version < low:
            continue
        if high is not None and version > high:
            continue
        if version in forbidden:
            continue
        if pin is not None and version != pin:
            continue
        rows.append(row)
    return rows


def _has_cycle(assignments, features):
    graph = {}
    for name, row in assignments.items():
        edges = []
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            edges.append(dep['name'])
        graph[name] = edges

    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return True
        if mark == 2:
            return False
        state[name] = 1
        for target in graph.get(name, ()):
            if visit(target):
                return True
        state[name] = 2
        return False

    return any(visit(name) for name in graph if state.get(name, 0) == 0)


def resolve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    limits = {}
    for name, interval in roots.items():
        if name not in packages:
            return {'error': 'unsatisfiable'}
        low, high = interval
        limits[name] = (low, high)

    best_vector = None
    best_versions = None

    def search(assignments, requirements):
        nonlocal best_vector, best_versions

        # An optimistic lexicographic bound lets us discard branches that
        # cannot improve the best complete installation found so far.
        upper = []
        for name in names:
            if name in assignments:
                upper.append(assignments[name]['version'])
                continue
            options = _allowed_rows(name, packages, requirements, blocked, pins)
            if name in requirements:
                if not options:
                    return
                upper.append(max(row['version'] for row in options))
            else:
                upper.append(max([-1] + [row['version'] for row in options]))
        upper = tuple(upper)
        if best_vector is not None and upper <= best_vector:
            return

        pending = [name for name in requirements if name not in assignments]
        if not pending:
            if _has_cycle(assignments, features):
                return
            vector = tuple(assignments[name]['version'] if name in assignments else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assignments[name]['version'] for name in assignments}
            return

        name = min(pending)
        options = _allowed_rows(name, packages, requirements, blocked, pins)
        options.sort(key=lambda row: row['version'], reverse=True)
        for row in options:
            next_assignments = dict(assignments)
            next_assignments[name] = row
            next_requirements = dict(requirements)
            possible = True
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                if target in next_requirements:
                    old_low, old_high = next_requirements[target]
                    low = max(low, old_low)
                    high = min(high, old_high)
                if low > high:
                    possible = False
                    break
                next_requirements[target] = (low, high)
                if target in next_assignments:
                    version = next_assignments[target]['version']
                    if version < low or version > high:
                        possible = False
                        break
            if possible:
                search(next_assignments, next_requirements)

    search({}, limits)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
